{"result":{"meta":null,"content":"CREATE TABLE IF NOT EXISTS pos_roles (\n  id TEXT PRIMARY KEY,\n  name TEXT NOT NULL UNIQUE,\n  permissions JSONB NOT NULL DEFAULT '[]'::jsonb,\n  is_system BOOLEAN NOT NULL DEFAULT false,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\nCREATE TABLE IF NOT EXISTS pos_users (\n  id TEXT PRIMARY KEY,\n  full_name TEXT NOT NULL,\n  email TEXT NOT NULL UNIQUE,\n  password_hash TEXT NOT NULL,\n  role_id TEXT NOT NULL REFERENCES pos_roles(id),\n  active BOOLEAN NOT NULL DEFAULT true,\n  must_change_password BOOLEAN NOT NULL DEFAULT false,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\nCREATE TABLE IF NOT EXISTS pos_sessions (\n  token_hash TEXT PRIMARY KEY,\n  user_id TEXT NOT NULL REFERENCES pos_users(id) ON DELETE CASCADE,\n  expires_at TIMESTAMPTZ NOT NULL,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\nCREATE INDEX IF NOT EXISTS idx_pos_sessions_user ON pos_sessions(user_id);\nCREATE INDEX IF NOT EXISTS idx_pos_sessions_expiry ON pos_sessions(expires_at);","structuredContent":null,"isError":false,"path":"migrations/0002_user_management.sql","hash":"3fd0ec502d8b4a98a214c716f2e6530472222b963e0453068be610069a301308","total_lines":27},"error":null,"error_data":null,"error_code":null,"classification_id":null,"json_rpc_error_code":null,"error_http_status_code":null,"error_http_headers":null,"internal":{"external_call_time_ms":776},"clamp_errors":null,"clamp_rewrites":null,"connector_id":"asdk_app_69e39e675b348191a4d52cf2bc580b79","connector_name":"Hatchable","action_name":"read_file","is_sync":false}